// <auto-generated/>
using System;
using Fanex.Razorbill.Security.Configurations;
using Fanex.Razorbill.Security.Entities;
using Fanex.Razorbill.Security.Sessions;
using Sunplus.Agent.Model.BL.Definitions;
using Sunplus.Agent.Model.Entities;
using Sunplus.Agent.Model.Entities.Permission;
using Sunplus.Agent.Utilities;
using Fanex.Caching;
using CasinoSetting;
using Sunplus.Agent.Model.BL.Bingo;
using Sunplus.Agent.Model.BL.Casino;
using System.Web;

public partial class Index : System.Web.UI.Page
{
    private const string DEFAULT_INDEX = "_Reports/PortalPage/PortalPage.aspx";
    protected string mainPage = null;
    protected string headerPage = "_Header/Header.aspx";
    protected string menuPage = "_Menu/Menu.aspx";

    protected override void OnLoad(EventArgs e)
    {
        // If the SecurityCodeSection has Active property is TRUE, then we will use the NEW flow of Security Code.
        // Otherwise the OLD one will be used.
        ISecurityCodeSession securityCodeSession = CookieLessSessionFactory.SecurityCodeSession;
        bool newFlowOfSC = SecurityCodeConfig.IsActive && securityCodeSession.IsRequireSecurityCode;
        SecurityCodeStatus status = (SecurityCodeStatus)securityCodeSession.SecurityCodeResult;

        SCResult oldStatus = UserSession.Current.SecurityCodeResult;
        if (!UserPermission.IsShowSecurityVerify)
        {
            oldStatus = SCResult.NONE;
        }

        if (!UserSession.Current.IsLogged)
        {
            mainPage = "_MemberInfo/ChangePassword/ChangePassword.aspx?firstLogin=true";
            menuPage = "../_blank.html";
        }
        else if (UserSession.Current.IsPasswordExpired)
        {
            mainPage = "_MemberInfo/ChangePassword/ChangePassword.aspx?expired=true";
            menuPage = "../_blank.html";
        }
        else if (newFlowOfSC)
        {
            // Use the NEW flow of Security Code.
            if (status == SecurityCodeStatus.FORCED_CHANGE_SC)
            {
                mainPage = "Security/SecurityCode/ForceChangeSecurityCode";
            }
            else if (status == SecurityCodeStatus.FORCED_CHANGE_SC_WITHOUT_VALIDATION)
            {
                mainPage = "Security/SecurityCode/ForceChangeSecurityCodeWithoutValidation";
            }
            else
            {
                mainPage = "Security/SecurityCode/VerifySecurityCode";
            }

            menuPage = "../_blank.html";
        }
        else if (!securityCodeSession.IsInternal &&
           (oldStatus == SCResult.FORCED_CHANGE_SC || oldStatus == SCResult.FORCED_CHANGE_SC_WITHOUT_VALIDATION))
        {
            // Use the OLD flow of Security Code.
            mainPage = "_MemberInfo/SecurityCode/ChangeSecurityCode.aspx";
            menuPage = "../_blank.html";
        }
        else
        {
            var currentURLCookie = Request.Cookies[CookieCurrentURLKey];
            string url = string.IsNullOrEmpty(UserSession.Current.RedirectReportLink) ?
                DEFAULT_INDEX :
                UserSession.Current.RedirectReportLink;

            if (currentURLCookie != null && !string.IsNullOrEmpty(currentURLCookie.Value) && !UserSession.Current.IsInternal)
            {
                if (!currentURLCookie.Value.Contains("Error.aspx")
                    && !currentURLCookie.Value.Contains("SignIn.aspx")
                    && !currentURLCookie.Value.Contains("ChangePassword.aspx")
                    && !currentURLCookie.Value.Contains("SecurityCode"))
                {
                    url = currentURLCookie.Value;
                }
            }

            mainPage = url;
        }

        Session["ph"] = Encryption.RandomString(new Random().Next(4, 8));
        InitializeCaching();

        // Hot fix for Opera browser (IIS does sniffing user agent)
        Response.ContentType = "text/html";
    }

    public string CookieCurrentURLKey
    {
        get
        {
            string name = string.Join("_", new string[] { 
               UserSession.Current.CustId.ToString(), 
               UserSession.Current.SubAccId.ToString(),
               "URL"
            });

            return Encryption.PearsonEncode(name);
        }
    }

    /// <summary>
    /// Initialize all configurations and caching one time only.
    /// </summary>
    public void InitializeCaching()
    {
        if (!initialized)
        {
            lock (locker)
            {
                if (!initialized)
                {
                    // Casino caching
                    try
                    {
                        SettingMgr.GetInstance().Initialize(SiteEnum.AgentSite);
                    }
                    catch { }

                    BingoBO bingo = new BingoBO(UserSession.Current.NetSessionId); // APILogger injection
                    CasinoBO casino = new CasinoBO(UserSession.Current.NetSessionId); // APILogger injection

                    // Init one time only
                    initialized = true;
                }
            }
        }
    }

    public static object locker = new object();
    public static bool initialized = false;
}

